// ============= v18.25: 难度自适应 helper =============
// v19.2: 全部 game minFloor=4 (PSLE考试AL1标准, 统一起步难度)
function _gameMinFloor(gameKey) {
  return 4;
}
// v19.82: 按题库真实覆盖动态封顶难度。
// 原来所有 game 都能升到 Lv6, 但 _sampleByDiff 在该档题不够时会静默回落到"全池随机",
// 结果孩子看到"Editing Lv6"、实际做的是 P4 题 — 既骗人又练不到东西。
// 规则: 取"至少还有 8 道题"的最高档 (一局 10 题, 允许少量跨档补齐)。
const _GAME_BANK_FOR_CAP = {
  math: () => typeof MATH_QUESTIONS !== 'undefined' && MATH_QUESTIONS,
  grammar: () => typeof GRAMMAR_QUESTIONS !== 'undefined' && GRAMMAR_QUESTIONS,
  cloze: () => typeof CLOZE_QUESTIONS !== 'undefined' && CLOZE_QUESTIONS,
  sst: () => typeof SST_QUESTIONS !== 'undefined' && SST_QUESTIONS,
  editing: () => typeof EDITING_PARAGRAPHS !== 'undefined' && EDITING_PARAGRAPHS,
  listen: () => typeof LISTEN_DICTATIONS !== 'undefined' && LISTEN_DICTATIONS,
  scimcq: () => typeof SCIENCE_MCQ !== 'undefined' && SCIENCE_MCQ,
  chinese: () => typeof CHINESE_MCQ !== 'undefined' && CHINESE_MCQ,
  unit: () => typeof UNIT_CONVERSIONS !== 'undefined' && UNIT_CONVERSIONS
};
const _gameMaxCapCache = {};
function _gameMaxCap(gameKey) {
  // v19.97: 原来算一次就永久缓存, 而且按"全库"算 —— 不扣已掌握的题。
  // 结果: 顶格档被 _markMastered 掏空后, cap 还显示 6, 于是 _sampleByDiff 的全池兜底
  // 开始塞 d3/d4 的题, 孩子看到"Lv6"实际做的是 P4 题(复核实测第12局起就这样)。
  // 现在按"还没掌握的题"实时算, 掌握得越多封顶会自己往下退, 显示的难度就是真的。
  let cap = 6;
  try {
    const getter = _GAME_BANK_FOR_CAP[gameKey];
    const bank = getter && getter();
    if (Array.isArray(bank) && bank.length) {
      const mastered = _masteredQs[gameKey] || new Set();
      const counts = {};
      bank.forEach((q, i) => { if (mastered.has(i)) return; const d = q.diff || q.difficulty || 0; counts[d] = (counts[d] || 0) + 1; });
      const usable = Object.keys(counts).map(Number).filter(d => counts[d] >= 7);   // 一局 Lv 档实发 7 道同档
      cap = usable.length ? Math.max(...usable) : _gameMinFloor(gameKey);
      cap = Math.max(cap, _gameMinFloor(gameKey));
    }
  } catch (e) { cap = 6; }
  return cap;
}
function recordGameRun(state, gameKey, correct, total) {
  const minFloor = _gameMinFloor(gameKey);
  if (!state.gameStats) state.gameStats = { vocab:{difficulty:4,recent:[]}, math:{difficulty:4,recent:[]}, editing:{difficulty:4,recent:[]}, listen:{difficulty:4,recent:[]}, cloze:{difficulty:4,recent:[]} };
  if (!state.gameStats[gameKey]) state.gameStats[gameKey] = { difficulty: minFloor, recent: [] };
  state.totalGameRuns = (state.totalGameRuns || 0) + 1;  // v18.58: 累积 mini-game 局数 (用于 game-runs 装备)
  const s = state.gameStats[gameKey];
  if (s.difficulty < minFloor) s.difficulty = minFloor;
  if (ENG_MODULE_OF_GAME[gameKey]) recordEngModule(state, ENG_MODULE_OF_GAME[gameKey], correct, total, gameKey);   // v22.0
  const acc = total > 0 ? correct / total : 0;
  s.recent.push({ date: new Date().toISOString().slice(0,10), correct, total, accuracy: acc });
  if (s.recent.length > 5) s.recent.shift();
  // 累积统计(无上限)
  if (!s.cumCorrect) s.cumCorrect = 0;
  if (!s.cumTotal) s.cumTotal = 0;
  if (!s.cumRuns) s.cumRuns = 0;
  s.cumCorrect += correct;
  s.cumTotal += total;
  s.cumRuns += 1;
  let levelChanged = null;
  const last3 = s.recent.slice(-3);
  const last2 = s.recent.slice(-2);
  // v19.81: 升级线 80% → 90% — AL1 的定义就是 90 分, 练习的通过线必须等于考试线。
  // 原来 80% 就跳档, 孩子在每一档都只练到 AL3/AL4 水平就被推走, 永远没机会在任何一档打磨到 90+
  if (s.difficulty < _gameMaxCap(gameKey) && last3.length === 3 && last3.every(r => r.accuracy >= 0.9)) {
    s.difficulty++;
    levelChanged = 'up';
    s.recent = [];
  } else if (s.difficulty > minFloor && last2.length === 2 && last2.every(r => r.accuracy <= 0.4)) {
    s.difficulty--;
    levelChanged = 'down';
    s.recent = [];
  }
  // v19.5: 弱科挑战 — 如果这次 game 属于弱科, 计入挑战进度
  const gameSubj = SUBJECT_OF_GAME[gameKey];
  if (gameSubj) {
    const weak = findWeakSubjects(state);
    if (weak.indexOf(gameSubj) >= 0) {
      recordWeakChallenge(state);
    }
  }
  return { newDiff: s.difficulty, levelChanged };
}

function getDifficulty(state, gameKey) {
  // v18.54: math = 4, 其他 = 4 (v19.2: 统一)
  const minFloor = _gameMinFloor(gameKey);
  let d = (state.gameStats && state.gameStats[gameKey]) ? state.gameStats[gameKey].difficulty || minFloor : minFloor;
  d = Math.max(minFloor, d);
  // v19.32: 英语 scaffold 弱生模式 cap (Expert 6 P1 — AL6 +20 gap 弱生需要难度分层)
  const ENGLISH_KEYS = ['grammar', 'cloze', 'sst', 'editing', 'listen_mcq'];
  const mode = state.englishMode || 'normal';
  if (mode === 'weak' && ENGLISH_KEYS.includes(gameKey)) {
    // v19.85: 原来压到 Lv2, 但目标已改成"英语 AL6 → AL1"。Lv2 是 P3-P4 难度,
    // 长期停在那里练不出 AL1。改为 Lv3 (仍比正常档低一级, 保留"不被压垮"的初衷)
    d = Math.min(d, 3);
  } else if (mode === 'strong' && ENGLISH_KEYS.includes(gameKey)) {
    d = Math.max(d, 4);  // 强生 Lv ≥ 4, 直接刷难题
  }
  return d;
}

// v19.32: English mode 自动升降级提示触发器
// 连对 5 题英语 → 建议升级; 连错 3 题英语 → 建议降级
function checkEnglishModeAdjust(state, gameKey, isCorrect) {
  const ENGLISH_KEYS = ['grammar', 'cloze', 'sst', 'editing', 'listen_mcq'];
  if (!ENGLISH_KEYS.includes(gameKey)) return null;
  if (!state.englishStreak) state.englishStreak = { correct: 0, wrong: 0 };
  if (isCorrect) {
    state.englishStreak.correct = (state.englishStreak.correct || 0) + 1;
    state.englishStreak.wrong = 0;
  } else {
    state.englishStreak.wrong = (state.englishStreak.wrong || 0) + 1;
    state.englishStreak.correct = 0;
  }
  const mode = state.englishMode || 'normal';
  if (mode === 'weak' && state.englishStreak.correct >= 5) {
    state.englishStreak.correct = 0;
    return { suggest: 'normal', reason: '连对 5 题! 可以试试 normal 模式挑战中等难度' };
  }
  if (mode === 'normal' && state.englishStreak.correct >= 8) {
    state.englishStreak.correct = 0;
    return { suggest: 'strong', reason: '连对 8 题! 可以挑战 strong 模式高难度' };
  }
  if (mode === 'strong' && state.englishStreak.wrong >= 3) {
    state.englishStreak.wrong = 0;
    return { suggest: 'normal', reason: '连错 3 题, 不如换 normal 模式稳一稳' };
  }
  if (mode === 'normal' && state.englishStreak.wrong >= 6) {
    // v19.85: 门槛从连错4题提到6题 — 冲 AL1 期间不该一遇挫折就往下劝退,
    // 但连错6题确实说明这一档太难, 该退一步把基础补稳
    state.englishStreak.wrong = 0;
    return { suggest: 'weak', reason: '连错 6 题, 先退一档把基础补稳, 站稳了再往上冲' };
  }
  return null;
}
window.checkEnglishModeAdjust = checkEnglishModeAdjust;

// 从池中按难度采样: 主难度 70% + ±1 难度 30%  (v18.97: 优先选未答题)
// v19.0: 答对的题永久排除 (mastered), 全 pool 都 mastered 才重置
const _usedQIndex = {};
let _masteredQs = {};  // { poolKey: Set<qIndex> } — 从 state.masteredQs 加载
function _loadMastered(state) {
  if (!state) return;
  if (state.masteredQs) Object.entries(state.masteredQs).forEach(([k, arr]) => { _masteredQs[k] = new Set(arr); });
  if (state.masteredHits) _masteredHits = JSON.parse(JSON.stringify(state.masteredHits));
}
// v19.91: 原来"答对一次就永久移出题池" —— 对冲 AL1 太松:
// 顶格档(Lv6)只有 8-15 道题, 一局好状态就把整档刷空, 之后 _sampleByDiff 只能发
// "换了选项顺序的变体", 那是在练认脸不是练会。改成**连对 2 次**才算掌握。
let _masteredHits = {};   // { poolKey: { qIndex: 连对次数 } }
function _markMastered(poolKey, pool, q) {
  if (!_masteredQs[poolKey]) _masteredQs[poolKey] = new Set();
  if (!_masteredHits[poolKey]) _masteredHits[poolKey] = {};
  const idx = pool.indexOf(q);
  if (idx < 0) return;
  const hits = (_masteredHits[poolKey][idx] || 0) + 1;
  _masteredHits[poolKey][idx] = hits;
  if (hits >= 2) _masteredQs[poolKey].add(idx);
}
// 答错则清零连对计数 (掌握必须是连续的, 不是累计的)
function _resetMasteredHit(poolKey, pool, q) {
  if (!_masteredHits[poolKey]) return;
  const idx = pool.indexOf(q);
  if (idx >= 0) delete _masteredHits[poolKey][idx];
}
function _saveMastered(state) {
  if (!state) return;
  state.masteredQs = {};
  Object.entries(_masteredQs).forEach(([k, s]) => {
    state.masteredQs[k] = [...s];
  });
  state.masteredHits = JSON.parse(JSON.stringify(_masteredHits));  // v19.91: 连对计数也要存
}
window._loadMastered = _loadMastered;
window._markMastered = _markMastered;
window._resetMasteredHit = _resetMasteredHit;
window._saveMastered = _saveMastered;

function _sampleByDiff(pool, diff, n) {
  const poolKey = pool === MATH_QUESTIONS ? 'math' : pool === GRAMMAR_QUESTIONS ? 'grammar' : pool === CLOZE_QUESTIONS ? 'cloze' : pool === UNIT_CONVERSIONS ? 'unit' : pool === EDITING_PARAGRAPHS ? 'editing' : pool === LISTEN_DICTATIONS ? 'listen' : pool === SCIENCE_CLASSIFY ? 'scilab' : pool === SCIENCE_MCQ ? 'scimcq' : pool === CHINESE_MCQ ? 'chinese' : pool === SST_QUESTIONS ? 'sst' : 'other';
  if (!_usedQIndex[poolKey]) _usedQIndex[poolKey] = new Set();
  const used = _usedQIndex[poolKey];
  const mastered = _masteredQs[poolKey] || new Set();

  // 排除已掌握的题
  const available = pool.filter((_, i) => !mastered.has(i));
  // v19.4: 全部掌握时生成错题变体 (换干扰项顺序 + 标 _variant)
  let effectivePool;
  if (available.length >= n) {
    effectivePool = available;
  } else {
    // 生成变体: 对错题本优先, 否则对全 pool 洗选项
    const wrongPool = (typeof state !== 'undefined' && state.wrongAnswers) ?
      pool.filter((q, i) => state.wrongAnswers.some(wa => wa.gameKey === poolKey && wa.qIndex === i)) : [];
    const variantBase = wrongPool.length >= n ? wrongPool : pool;
    effectivePool = variantBase.map(q => {
      if (!q.opts) return q;
      const newOpts = (function (a) { const b = [...a]; for (let i = b.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); const t = b[i]; b[i] = b[j]; b[j] = t; } return b; })(q.opts);
      const newAns = newOpts.indexOf(q.opts[q.ans]);
      return Object.assign({}, q, { opts: newOpts, ans: newAns, _variant: true });
    });
  }

  const main = effectivePool.filter(p => p.diff === diff);
  const near = effectivePool.filter(p => Math.abs(p.diff - diff) === 1);
  const combined = [...main, ...near, ...pool.filter(p => Math.abs(p.diff - diff) > 1)];

  // 分为未用过 vs 已用过
  const fresh = combined.filter((_, i) => !used.has(combined.indexOf(pool[pool.indexOf(combined[i])])));
  const stale = combined.filter((_, i) => used.has(combined.indexOf(pool[pool.indexOf(combined[i])])));

  // 简化: 用 pool index 标记
  const freshMain = main.filter(q => !used.has(pool.indexOf(q)));
  const freshNear = near.filter(q => !used.has(pool.indexOf(q)));
  const staleMain = main.filter(q => used.has(pool.indexOf(q)));
  const staleNear = near.filter(q => used.has(pool.indexOf(q)));

  const shuffle = arr => arr.map(x => [Math.random(), x]).sort((a,b) => a[0]-b[0]).map(x => x[1]);
  const out = [];
  const mainCount = Math.ceil(n * 0.7);

  // 优先从未用过的题中选
  const fm = shuffle(freshMain);
  const fn = shuffle(freshNear);
  for (let i = 0; i < mainCount && i < fm.length; i++) out.push(fm[i]);
  for (let i = 0; out.length < n && i < fn.length; i++) out.push(fn[i]);

  // 不够则用已用过的(洗牌后重来)
  if (out.length < n) {
    const sm = shuffle(staleMain);
    for (let i = 0; out.length < n && i < sm.length; i++) out.push(sm[i]);
  }
  if (out.length < n) {
    const sn = shuffle(staleNear);
    for (let i = 0; out.length < n && i < sn.length; i++) out.push(sn[i]);
  }
  // 再不够从全池补 —— v19.97: 但不许跌破 diff-1, 否则"Lv6"会静默发 P4 题。
  // 这是 v19.82 想堵的洞, 当时只改了 cap, 兜底这一层原样漏着。
  if (out.length < n) {
    const floor = Math.max(1, diff - 1);
    const rest = shuffle(pool.filter(p => !out.includes(p) && (p.diff || p.difficulty || 0) >= floor));
    for (let i = 0; out.length < n && i < rest.length; i++) out.push(rest[i]);
  }
  // 实在凑不齐(该档题被刷光)才允许全池, 宁可重复也不降级
  if (out.length < n) {
    const any = shuffle(pool.filter(p => !out.includes(p) && (p.diff || p.difficulty || 0) >= Math.max(1, diff - 1)));
    for (let i = 0; out.length < n && i < any.length; i++) out.push(any[i]);
  }

  const result = out.slice(0, n);
  // 标记为已用
  result.forEach(q => used.add(pool.indexOf(q)));
  // 所有题用完则重置(循环)
  if (used.size >= pool.length) used.clear();

  return result;
}

function getMathQuestionsByDiff(diff, n) {
  return _sampleByDiff(MATH_QUESTIONS, diff, n || 10);
}

// v19.34: Paper 1 (无计算器, 速算/直选) vs Paper 2 (problem sums, 含 $/比例/几何应用)
// 启发式 auto-tag: 含 $ 或长描述 (≥18 char) 或含中文应用描述词 → P2; 其他 → P1
function _autoTagMathPaper(q) {
  if (q._paper) return q._paper;
  const text = q.q || '';
  // P2 indicators
  const P2_KEYWORDS = ['$', '原 (', '余 (', '甲', '乙', '工程', '几天', '比例', '几只', '几张', '几辆', '原价', '面积', '体积', '速度', '小时', 'cm²', 'cm³', '总价'];
  const hasP2Keyword = P2_KEYWORDS.some(kw => text.includes(kw));
  const isLong = text.length >= 18;
  q._paper = (hasP2Keyword || isLong) ? 2 : 1;
  return q._paper;
}
function tagAllMathPapers() {
  MATH_QUESTIONS.forEach(_autoTagMathPaper);
}
function getMathQuestionsByPaper(diff, n, paper) {
  if (!MATH_QUESTIONS[0]._paper) tagAllMathPapers();
  const pool = paper ? MATH_QUESTIONS.filter(q => q._paper === paper) : MATH_QUESTIONS;
  return _sampleByDiff(pool, diff, n || 10);
}
function getMathPaperCounts() {
  if (!MATH_QUESTIONS[0]._paper) tagAllMathPapers();
  let p1 = 0, p2 = 0;
  MATH_QUESTIONS.forEach(q => { if (q._paper === 1) p1++; else p2++; });
  return { p1, p2 };
}

// v19.3: Mini-game 本周关联模式 — 优先出与本周主题相关的题
function getWeeklyLinkedQuestions(pool, weekN, diff, n) {
  n = n || 10;
  const theme = (WEEK_TASKS[weekN - 1] && WEEK_TASKS[weekN - 1].theme) || '';
  const keywords = theme.toLowerCase().replace(/[⭐🎯🔬📖]/g, '').split(/[\s/+—]+/).filter(w => w.length > 2);
  const linked = pool.filter(q => {
    const text = ((q.q || '') + ' ' + (q.explain || '') + ' ' + (q.topic || '')).toLowerCase();
    return keywords.some(kw => text.includes(kw));
  });
  const fromLinked = _sampleByDiff(linked.length > 0 ? linked : pool, diff, Math.min(Math.ceil(n * 0.6), linked.length));
  const rest = _sampleByDiff(pool.filter(q => !fromLinked.includes(q)), diff, n - fromLinked.length);
  return [...fromLinked, ...rest].slice(0, n);
}
function getEditingByDiff(diff) {
  const arr = _sampleByDiff(EDITING_PARAGRAPHS, diff, 1);
  return arr[0] || EDITING_PARAGRAPHS[0];
}
function getListenByDiff(diff) {
  const arr = _sampleByDiff(LISTEN_DICTATIONS, diff, 1);
  return arr[0] || LISTEN_DICTATIONS[0];
}

// 词汇按难度: 1-2 用本周 vocab, 3+ 加 VOCAB_HARD; 5 混入句子
function getVocabPairsByDiff(diff, weekN, n) {
  n = n || 6;
  const v = window.getVocabForWeek ? window.getVocabForWeek(weekN) : null;
  let basePairs = [];
  if (v && v.section && v.section.words) {
    const words = v.section.words.filter(w => VOCAB_MEANINGS && VOCAB_MEANINGS[w]);
    basePairs = words.map(w => ({ en: w, zh: VOCAB_MEANINGS[w], kind: 'word' }));
  }
  // diff 3+ 加 VOCAB_HARD 词
  if (diff >= 3) {
    const hardWords = VOCAB_HARD.filter(h => h.diff <= diff && h.diff >= diff - 1);
    basePairs = basePairs.concat(hardWords.map(h => ({ en: h.en, zh: h.zh, kind: 'word' })));
  }
  // 洗牌取词
  const sh = basePairs.map(p => [Math.random(), p]).sort((a,b) => a[0]-b[0]).map(p => p[1]);
  let result = sh.slice(0, n);
  // diff 4+ 强制混入 1-2 个句子卡 (替换最后 1-2 个 word)
  if (diff >= 4) {
    const sentPool = VOCAB_HARD.filter(h => h.sent && h.diff <= diff);
    const sShuf = sentPool.map(x => [Math.random(), x]).sort((a,b) => a[0]-b[0]).map(x => x[1]);
    const sentCount = diff === 4 ? 1 : 2;
    for (let i = 0; i < sentCount && i < sShuf.length; i++) {
      const s = sShuf[i];
      result[result.length - 1 - i] = { en: s.sent, zh: '【句】' + s.zh, kind: 'sent' };
    }
  }
  return result;
}

