const SCIENCE_CLASSIFY = [{"topic":"动物分类: 脊椎 vs 无脊椎","cats":["脊椎动物","无脊椎动物"],"diff":1,"items":[{"n":"鱼","c":0},{"n":"蝴蝶","c":1},{"n":"青蛙","c":0},{"n":"蜘蛛","c":1},{"n":"鸟","c":0},{"n":"蜗牛","c":1}]},{"topic":"植物: 开花 vs 不开花","cats":["开花植物","不开花植物"],"diff":1,"items":[{"n":"玫瑰","c":0},{"n":"蕨类","c":1},{"n":"向日葵","c":0},{"n":"苔藓","c":1},{"n":"樱花","c":0},{"n":"地钱","c":1}]},{"topic":"材料: 导体 vs 绝缘体","cats":["导体","绝缘体"],"diff":2,"items":[{"n":"铜","c":0},{"n":"塑料","c":1},{"n":"铁","c":0},{"n":"橡胶","c":1},{"n":"银","c":0},{"n":"木头","c":1},{"n":"玻璃","c":1}]},{"topic":"动物分类: 哺乳/鸟/鱼/爬行","cats":["哺乳","鸟类","鱼类","爬行类"],"diff":3,"items":[{"n":"狗","c":0},{"n":"鹰","c":1},{"n":"鲨鱼","c":2},{"n":"蛇","c":3},{"n":"蝙蝠","c":0},{"n":"企鹅","c":1},{"n":"鳄鱼","c":3}]},{"topic":"物质三态: 固/液/气","cats":["固体","液体","气体"],"diff":2,"items":[{"n":"冰","c":0},{"n":"水","c":1},{"n":"水蒸气","c":2},{"n":"石头","c":0},{"n":"果汁","c":1},{"n":"氧气","c":2}]},{"topic":"能量形式","cats":["热能","光能","电能","声能","化学能"],"diff":4,"items":[{"n":"电池","c":4},{"n":"食物","c":4},{"n":"插着电的电风扇(输入)","c":2},{"n":"乐器","c":3},{"n":"扬声器","c":3},{"n":"熨斗(输出)","c":0},{"n":"手电筒(输出)","c":1}]},{"topic":"生命周期: 完全/不完全变态","cats":["完全变态","不完全变态"],"diff":4,"items":[{"n":"蝴蝶","c":0},{"n":"蝗虫","c":1},{"n":"蚊子","c":0},{"n":"蝉","c":1},{"n":"蜜蜂","c":0},{"n":"蟋蟀","c":1}]},{"topic":"光: 反射 vs 吸收","cats":["反射光","吸收光"],"diff":3,"items":[{"n":"镜子","c":0},{"n":"黑布","c":1},{"n":"金属表面","c":0},{"n":"深色衣服","c":1},{"n":"白墙","c":0},{"n":"黑色窗帘","c":1}]},{"topic":"环境因素","cats":["生物因素","非生物因素"],"diff":3,"items":[{"n":"植物","c":0},{"n":"阳光","c":1},{"n":"细菌","c":0},{"n":"温度","c":1},{"n":"动物","c":0},{"n":"水","c":1},{"n":"空气","c":1}]},{"topic":"电路: 串联/并联","cats":["串联","并联"],"diff":5,"items":[{"n":"圣诞灯一坏全灭","c":0},{"n":"家用插座","c":1},{"n":"手电筒里的两节电池","c":0},{"n":"一条街的路灯(一盏坏其余亮)","c":1}]}];

// helpers
function getUnitByDiff(diff, n) { return _sampleByDiff(UNIT_CONVERSIONS, diff, n || 10); }
