  let seed = 20261002; const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;   // 固定种子: 同样的输入出同样的日期
  let n = 0, learnedDay = null, masteredDay = null, introDay = null, p95Day = null;
