  const extra = buildDailyFlashcardGroup(state, null, new Set(g.words));
  if (!extra.length) return { added: 0, why: 'empty' };
  g.newCount = (g.newCount || 0) + extra.filter(w => !(state.flashcardSRS || {})[w]).length;
  g.words = g.words.concat(extra);
  g.queue = extra.slice();
  g.done = false;
  g.extra = (g.extra || 0) + 1;
