// =========== v19.35: 置信度机制 + 月度模考评分 (第 11 轮 P0 修复) ===========

// 单科 raw mark → AL band (MOE 真实 cut-off)
function rawMarkToAL(score) {
  if (score >= 90) return 1;
  if (score >= 85) return 2;
  if (score >= 80) return 3;
  if (score >= 75) return 4;
  if (score >= 65) return 5;
  if (score >= 45) return 6;
  if (score >= 20) return 7;
  return 8;
}

// 信任度 5 档 + AL ± N 区间宽度 (Plan agent 验证: 方差替代 Wilson, 月考唯一通路)
function getConfidenceLevel(state) {
  const monthly = (state && state.monthlyMockHistory) || [];
  const count = monthly.length;
  if (state && state.psleDone) {
    return { stars: 5, alWidth: 0, schoolWidth: 0, monthlyCount: count, reason: 'PSLE 真考已完成 — 实测无误差' };
  }
  if (count >= 6) {
    // ★4 需近 2 次总 AL 极差 ≤ 1 (防偶发高分升级)
    const last2 = monthly.slice(-2).map(m => m.totalAL || 32);
    const range = Math.abs(last2[0] - last2[1]);
    if (range <= 1) {
      return { stars: 4, alWidth: 2, schoolWidth: 15, monthlyCount: count, reason: `${count} 次月考 + 近 2 次综合 AL 稳定 (极差 ${range})` };
    }
    // 月考 ≥6 但近 2 次仍波动 → 保持 ★3
    return { stars: 3, alWidth: 3, schoolWidth: 25, monthlyCount: count, reason: `${count} 次月考但近 2 次波动 (极差 ${range}), 需稳定后升 ★4` };
  }
  if (count >= 3) {
    return { stars: 3, alWidth: 3, schoolWidth: 25, monthlyCount: count, reason: `${count} 次月考, 数据中等可信` };
  }
  if (count >= 1) {
    return { stars: 2, alWidth: 4, schoolWidth: 35, monthlyCount: count, reason: `${count} 次月考, 数据稀薄` };
  }
  return { stars: 1, alWidth: 5, schoolWidth: 45, monthlyCount: 0, reason: '零月考数据, 全是 mini-game 难度推算' };
}

// 录取概率带 CI (clamp [4,30] 防边界错档, Plan agent 修订)
function admissionProbabilityWithCI(childAL, schoolCOP, alWidth) {
  const center = admissionProbability(childAL, schoolCOP);
  const lo = admissionProbability(Math.min(30, childAL + (alWidth || 0)), schoolCOP);  // 悲观 (AL 高 = 概率低)
  const hi = admissionProbability(Math.max(4, childAL - (alWidth || 0)), schoolCOP);   // 乐观
  return { center, lower: lo, upper: hi };
}

// 月度模考抽题 — 弱科加权 (英 12 / 数 10 / 科 8 / 华 5 = 35 题)
function getMonthlyMockQuestions() {
  const shuffle = arr => [...arr].sort(() => Math.random() - 0.5);
  const sample = (arr, n) => shuffle(arr).slice(0, n);
  const eng = [
    ...sample((typeof GRAMMAR_QUESTIONS !== 'undefined' ? GRAMMAR_QUESTIONS : []).filter(q => (q.diff || 3) >= 3), 5).map(q => ({ ...q, _subj: 'eng', _kind: 'grammar', _qField: 'q' })),
    ...sample((typeof CLOZE_QUESTIONS !== 'undefined' ? CLOZE_QUESTIONS : []).filter(q => (q.diff || 3) >= 3), 4).map(q => ({ ...q, _subj: 'eng', _kind: 'cloze', _qField: 'sentence' })),
    ...sample((typeof SST_QUESTIONS !== 'undefined' ? SST_QUESTIONS : []).filter(q => (q.diff || 3) >= 3), 3).map(q => ({ ...q, _subj: 'eng', _kind: 'sst', _qField: 'q' }))
  ];
  const math = [];
  if (typeof MATH_QUESTIONS !== 'undefined') {
    if (!MATH_QUESTIONS[0]._paper && typeof tagAllMathPapers === 'function') tagAllMathPapers();
    const p1Pool = MATH_QUESTIONS.filter(q => q._paper === 1 && (q.diff || 3) >= 3);
    const p2Pool = MATH_QUESTIONS.filter(q => q._paper === 2 && (q.diff || 3) >= 3);
    math.push(...sample(p1Pool, 6).map(q => ({ ...q, _subj: 'math', _kind: 'math_p1', _qField: 'q' })));
    math.push(...sample(p2Pool, 4).map(q => ({ ...q, _subj: 'math', _kind: 'math_p2', _qField: 'q' })));
  }
  const sci = [
    ...sample((typeof SCIENCE_MCQ !== 'undefined' ? SCIENCE_MCQ : []).filter(q => (q.difficulty || q.diff || 3) >= 3), 5).map(q => ({ ...q, _subj: 'sci', _kind: 'sci_mcq', _qField: 'q' })),
    ...sample((typeof SCIENCE_OE_QUESTIONS !== 'undefined' ? SCIENCE_OE_QUESTIONS : []), 3).map(q => ({ ...q, _subj: 'sci', _kind: 'sci_oe', _qField: 'q' }))
  ];
  const chi = sample((typeof CHINESE_MCQ !== 'undefined' ? CHINESE_MCQ : []), 5).map(q => ({ ...q, _subj: 'chi', _kind: 'chi_mcq', _qField: 'q' }));
  return { eng, math, sci, chi, total: eng.length + math.length + sci.length + chi.length };
}

// 单次月考完成 → 算 4 科 AL + 写入历史
function recordMonthlyMock(state, scores, rubricHits, durationSec) {
  if (!state.monthlyMockHistory) state.monthlyMockHistory = [];
  const alBands = {
    eng: rawMarkToAL(scores.eng || 0),
    math: rawMarkToAL(scores.math || 0),
    sci: rawMarkToAL(scores.sci || 0),
    chi: rawMarkToAL(scores.chi || 0)
  };
  const totalAL = alBands.eng + alBands.math + alBands.sci + alBands.chi;
  const entry = {
    ts: Date.now(),
    scores, alBands, totalAL,
    durationSec: durationSec || 0,
    rubricHits: rubricHits || {}
  };
  state.monthlyMockHistory.push(entry);
  // 同步更新 subjectALEstimates (用最新月考结果覆盖)
  if (state.subjectALEstimates) {
    state.subjectALEstimates.english = alBands.eng;
    state.subjectALEstimates.math = alBands.math;
    state.subjectALEstimates.science = alBands.sci;
    state.subjectALEstimates.chinese = alBands.chi;
    state.subjectALEstimates.lastUpdate = Date.now();
  }
  return entry;
}

// 录取概率公式 (简化正态 CDF — delta = COP - childAL, 越正越好)
function admissionProbability(childAL, schoolCOP) {
  const delta = schoolCOP - childAL;
  if (delta >= 3) return 98;
  if (delta >= 2) return 92;
  if (delta >= 1) return 82;
  if (delta >= 0) return 65;
  if (delta >= -1) return 35;
  if (delta >= -2) return 15;
  if (delta >= -3) return 5;
  return 1;
}

// 综合 AL → 新加坡 P6 排名估算
function estimateSGRank(totalAL) {
  if (totalAL <= 8) return 5;
  if (totalAL <= 10) return 15;
  if (totalAL <= 12) return 25;
  if (totalAL <= 16) return 40;
  if (totalAL <= 20) return 60;
  return 80;
}

// mini-game 难度 → AL 估算
function _gameDiffToAL(diff, subject) {
  // v19.81 修死结: 原 map 缺 diff=6, 打到最高难度反而落到 `|| 6` 被判 AL6 — 越努力评级越差。
  // diff 6/5 = AL1, 4 = AL2, 3 = AL4, 2 = AL6, 1 = AL7; 未知档按最差算(8)不冒充 AL6
  const map = { 6: 1, 5: 1, 4: 2, 3: 4, 2: 6, 1: 7 };
  return map[diff] || 8;
}

// 计算综合 PSLE 预测 AL (核心) — v19.15k: 永远 auto 算, 不读 manual override
function computeTotalAL(state) {
  const est = state.subjectALEstimates || { english: 6, math: 1, science: 3, chinese: 2 };  // v19.81: 对齐 2026-08 校考实测(英6/数1/科3/华2 = AL12)
  // 英语: 取 Paper 2 模拟卷最近 4 次预测 AL 平均, 没有则用 est.english fallback
  const p2Hist = state.paper2ALHistory || [];
  let english_AL = est.english;
  if (p2Hist.length > 0) {
    const recent = p2Hist.slice(-4);
    english_AL = Math.round(recent.reduce((s, h) => s + (h.predictedAL || 6), 0) / recent.length);
  }
  // 数学: 用 gameStats.math 难度
  const mathDiff = state.gameStats?.math?.difficulty || 4;
  const math_AL = Math.min(_gameDiffToAL(mathDiff), est.math);  // 取更好的
  // 科学: 用 gameStats.scilab + scimcq + est
  const sciDiff = Math.max(state.gameStats?.scilab?.difficulty || 3, state.gameStats?.scimcq?.difficulty || 3);
  const science_AL = Math.min(_gameDiffToAL(sciDiff), est.science);
  // 华文: MCQ 难度档 + 阅读问答踩点率, 取更差的那个
  // v20.0 修: 2026-08 校考华文 43/50 = AL2, 丢的 7 分全在阅读大题"2分题只写1个点"。
  // 只看 MCQ 难度档会算出"华文 AL1", 比真实卷面高一整档 — 病在开放题, 就得让开放题的
  // 踩点率有权把 AL 拉回来, 否则 app 一直报喜, 孩子直到考场才知道漏点没治。
  const chineseDiff = state.gameStats?.chinese?.difficulty || 3;
  let chinese_AL = Math.min(_gameDiffToAL(chineseDiff), est.chinese);
  const cnOe = state.gameStats && state.gameStats.cn_oe;
  if (cnOe && (cnOe.cumRuns || 0) >= 2 && (cnOe.cumTotal || 0) > 0) {
    const oeAL = scoreToAL(cnOe.cumCorrect / cnOe.cumTotal * 100);
    chinese_AL = Math.max(chinese_AL, oeAL);  // AL 数字越大越差 → max = 取更差的
  }

  const total_AL = english_AL + math_AL + science_AL + chinese_AL;
  return {
    bySubject: { english_AL, math_AL, science_AL, chinese_AL },
    total_AL,
    sgRank_pct: estimateSGRank(total_AL)
  };
}

// v19.15k: getAdmissionForecasts 兼容 whatIfBySubject 临时覆盖 (用于 what-if 模拟, 不动 state)
function _buildSchools(total_AL, bySubject) {
  return PSLE_TARGET_SCHOOLS.map(s => ({
    ...s,
    probability: admissionProbability(total_AL, s.cop)
  }));
}

// 获取所有目标校录取预测 (主页录取概率卡用)
// v19.15k: 加 whatIfBySubject 可选参数 (例 {english:3, math:1, science:2, chinese:1}) 临时模拟"如果调到这个 AL"
function getAdmissionForecasts(state, whatIfBySubject) {
  const realCalc = computeTotalAL(state);
  // 若 whatIf 存在, 用它覆盖 4 科算"模拟" total_AL (real 仍保留对比)
  let effectiveBySubject = realCalc.bySubject;
  let effectiveTotalAL = realCalc.total_AL;
  let isWhatIf = false;
  if (whatIfBySubject && typeof whatIfBySubject === 'object') {
    const w = whatIfBySubject;
    effectiveBySubject = {
      english_AL: Math.max(1, Math.min(8, w.english || realCalc.bySubject.english_AL)),
      math_AL: Math.max(1, Math.min(8, w.math || realCalc.bySubject.math_AL)),
      science_AL: Math.max(1, Math.min(8, w.science || realCalc.bySubject.science_AL)),
      chinese_AL: Math.max(1, Math.min(8, w.chinese || realCalc.bySubject.chinese_AL))
    };
    effectiveTotalAL = effectiveBySubject.english_AL + effectiveBySubject.math_AL + effectiveBySubject.science_AL + effectiveBySubject.chinese_AL;
    isWhatIf = (effectiveTotalAL !== realCalc.total_AL);
  }
  const schools = PSLE_TARGET_SCHOOLS.map(s => ({
    ...s,
    probability: admissionProbability(effectiveTotalAL, s.cop)
  }));
  // 算英语提到 AL3 的预期: 综合 -3, 各校概率
  const ifEngAL3 = {
    total_AL: effectiveBySubject.english_AL > 3
      ? effectiveTotalAL - (effectiveBySubject.english_AL - 3)
      : effectiveTotalAL,
    schools: PSLE_TARGET_SCHOOLS.map(s => ({
      ...s,
      probability: admissionProbability(
        effectiveBySubject.english_AL > 3 ? effectiveTotalAL - (effectiveBySubject.english_AL - 3) : effectiveTotalAL,
        s.cop
      )
    }))
  };
  return {
    bySubject: effectiveBySubject,
    total_AL: effectiveTotalAL,
    sgRank_pct: estimateSGRank(effectiveTotalAL),
    isWhatIf,
    realBySubject: realCalc.bySubject,
    realTotalAL: realCalc.total_AL,
    schools,
    ifEnglishImproved: ifEngAL3
  };
}

// 记录 Paper 2 模拟卷结果 (从 _finishMcqGame g.isMock 分支调用)
function recordPaper2AL(state, predictedAL, score, total) {
  if (!state.paper2ALHistory) state.paper2ALHistory = [];
  state.paper2ALHistory.push({
    date: new Date().toISOString().slice(0, 10),
    predictedAL, score, total,
    timestamp: Date.now()
  });
  // 保留最近 20 次 (够算 4 周连续)
  while (state.paper2ALHistory.length > 20) state.paper2ALHistory.shift();
}

window.PSLE_TARGET_SCHOOLS = PSLE_TARGET_SCHOOLS;
window.admissionProbability = admissionProbability;
window.estimateSGRank = estimateSGRank;
// v19.35: 置信度机制 + 月考
window.getConfidenceLevel = getConfidenceLevel;
window.admissionProbabilityWithCI = admissionProbabilityWithCI;
window.rawMarkToAL = rawMarkToAL;
window.getMonthlyMockQuestions = getMonthlyMockQuestions;
window.recordMonthlyMock = recordMonthlyMock;
window.computeTotalAL = computeTotalAL;
window.getAdmissionForecasts = getAdmissionForecasts;
