    if (CORE_DICT[key]) { const m = /^(.*?)\(([a-z.\/ ]+)\)\s*$/.exec(CORE_DICT[key]); return { word: key, zh: m ? m[1] : CORE_DICT[key], pos: m ? m[2] : '', en: '', ipa: getVocabIpa(key), src: 'core' }; }
